import { VercelRequest, VercelResponse } from '@vercel/node';
import crypto from 'crypto';

/**
 * SERVE PORTRAITPOP
 *
 * PortraitPop is NOT a static file on this site. Its HTML lives inside this
 * function as PORTRAITPOP_HTML_B64, so there is no address to bookmark or share.
 * This route is the only way to get the tool, and it requires an unexpired pass
 * minted by /api/portraitpop-pass for a signed-in adviser.
 *
 * On success we write an eight-hour session pass into the page as
 * window.__PORTRAITPOP_SESSION. PortraitPop sends that to /api/portraitpop-verify
 * before building a PDF, so a saved copy of the page stops exporting.
 *
 * TO UPDATE THE TOOL: the HTML is base64 at the bottom of this file. Send the new
 * index.html to Claude and replace this whole file with the regenerated one.
 */

// ---------------------------------------------------------------------------
// Pass signing. Duplicated in each PortraitPop route on purpose, so these
// functions carry no dependency on any other file in the repo.
//
//   'open'    ~2 minutes. Spent immediately to load the tool.
//   'session' ~8 hours. Lives inside the page; the tool checks it before export.
//
// A pass is  base64url(JSON) + "." + base64url(HMAC-SHA256). Nothing secret is
// inside it; the signature is what makes it unforgeable.
// ---------------------------------------------------------------------------

const OPEN_PASS_MS = 2 * 60 * 1000;
const SESSION_PASS_MS = 8 * 60 * 60 * 1000;

interface PassPayload { typ: 'open' | 'session'; email: string; exp: number; }

function getSecret(): string | null {
  const s = process.env.PORTRAITPOP_SECRET;
  return (s && s.length >= 16) ? s : null;
}

function signPass(payload: PassPayload, secret: string): string {
  const body = Buffer.from(JSON.stringify(payload)).toString('base64url');
  const sig = crypto.createHmac('sha256', secret).update(body).digest('base64url');
  return body + '.' + sig;
}

function verifyPass(pass: any, secret: string, expectedType: 'open' | 'session'): PassPayload | null {
  try {
    const raw = String(pass || '');
    const dot = raw.indexOf('.');
    if (dot < 1) return null;
    const body = raw.slice(0, dot);
    const sig = raw.slice(dot + 1);
    if (!body || !sig) return null;
    const expect = crypto.createHmac('sha256', secret).update(body).digest('base64url');
    if (sig.length !== expect.length) return null;
    if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expect))) return null;
    const data = JSON.parse(Buffer.from(body, 'base64url').toString('utf8'));
    if (!data || data.typ !== expectedType) return null;
    if (typeof data.exp !== 'number' || Date.now() > data.exp) return null;
    if (!data.email) return null;
    return data as PassPayload;
  } catch (e) {
    return null;
  }
}

function denied(res: VercelResponse, message: string) {
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.setHeader('Cache-Control', 'no-store');
  return res.status(401).send('<!DOCTYPE html><html><head><meta charset="utf-8">'
    + '<meta name="viewport" content="width=device-width, initial-scale=1">'
    + '<meta name="robots" content="noindex, nofollow"><title>PortraitPop</title><style>'
    + 'body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;'
    + 'background:linear-gradient(135deg,#ecfeff 0%,#f0fdfa 100%);'
    + 'font-family:system-ui,-apple-system,"Segoe UI",sans-serif;padding:24px}'
    + '.card{background:#fff;border-radius:16px;box-shadow:0 10px 40px rgba(0,0,0,.10);'
    + 'padding:38px 34px;max-width:440px;text-align:center}'
    + 'h1{margin:0 0 12px;font-size:21px;color:#0f172a}'
    + 'p{margin:0 0 22px;font-size:15px;color:#475569;line-height:1.6}'
    + 'a{display:inline-block;background:#14b8a6;color:#fff;text-decoration:none;'
    + 'font-weight:700;padding:13px 26px;border-radius:10px}'
    + '</style></head><body><div class="card"><h1>This link has expired</h1><p>'
    + message + '</p><a href="/">Go to my Dashboard</a></div></body></html>');
}

export default async function handler(req: VercelRequest, res: VercelResponse) {
  const secret = getSecret();
  if (!secret) {
    console.error('PORTRAITPOP_SECRET is missing or shorter than 16 characters');
    return denied(res, 'PortraitPop is not configured yet. Please call us at 888-680-0143.');
  }

  try {
    const payload = verifyPass((req.query.pass as string) || '', secret, 'open');
    if (!payload) {
      return denied(res, 'PortraitPop opens from the Quick Links tab of your dashboard. Please open it from there.');
    }

    const sessionPass = signPass(
      { typ: 'session', email: payload.email, exp: Date.now() + SESSION_PASS_MS },
      secret
    );

    let html = Buffer.from(PORTRAITPOP_HTML_B64, 'base64').toString('utf8');

    // Hand the session pass to the tool. Both routes are supported: a literal
    // __PORTRAITPOP_SESSION__ placeholder if the HTML has one, and a global that
    // is always available.
    if (html.indexOf('__PORTRAITPOP_SESSION__') !== -1) {
      html = html.split('__PORTRAITPOP_SESSION__').join(sessionPass);
    }
    const inject = '<script>window.__PORTRAITPOP_SESSION=' + JSON.stringify(sessionPass)
      + ';window.__PORTRAITPOP_VERIFY_URL="/api/portraitpop-verify";</script>';
    html = html.replace('<head>', '<head>' + inject);

    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
    res.setHeader('X-Robots-Tag', 'noindex, nofollow, noarchive');
    res.setHeader('Referrer-Policy', 'no-referrer');
    return res.status(200).send(html);

  } catch (error) {
    console.error('portraitpop serve error:', error);
    return denied(res, 'Something went wrong loading PortraitPop. Please try again from your dashboard.');
  }
}

// ---------------------------------------------------------------------------
// The tool itself, base64 encoded. Do not edit by hand.
// ---------------------------------------------------------------------------
const PORTRAITPOP_HTML_B64 = "";
